mapper.select:
select c.classroom_id as classroomId, c.classroom_name as classroomName, b.building_name as buildingName, ct.type_name as typeName, c.capacity as capacity, count(o.offering_id) as scheduleCount, coalesce(sum(case when o.offering_id is not null then (s.end_period - s.start_period + 1) else 0 end), 0) as weeklySessions from brm_classroom c left join brm_building b on c.building_id = b.building_id left join brm_classroom_type ct on c.type_id = ct.type_id left join tpm_schedule s on s.classroom_id = c.classroom_id and s.del_flag = '0' and s.status = '0' left join tpm_course_offering o on s.offering_id = o.offering_id and o.del_flag = '0' and o.semester_id = #{semesterId}
c.status = '0' and c.building_id = #{buildingId}
group by c.classroom_id, c.classroom_name, b.building_name, ct.type_name, c.capacity order by weeklySessions desc, c.classroom_name asc
